    'BAZ_EXTERNAL_IDS_REMOVED' => 'இந்தப் பட்டியல் மற்றொரு wiki-யின் பதிவுகளைக் (%{ids}) கேட்டது, அது இனி காட்சியின்போது செய்யப்படுவதில்லை: வெளிப்புற உள்ளடக்கங்கள் இப்போது இந்த wiki-யில் இறக்குமதி செய்யப்படுகின்றன — தேடக்கூடியதாக இருக்க, இந்த wiki-யின் உரிமைகளை மதிக்க, மற்ற தளம் இல்லாதபோதும் கிடைக்கும்படி இருக்க. ஒரு நிர்வாகி இறக்குமதியாளர்களின் நிர்வாகத் திரையிலிருந்து இறக்குமதியை அமைத்து, பிறகு இந்தப் பட்டியலை உள்ளூர்ப் படிவத்தை நோக்கிச் சுட்டலாம்.',
