    'IMPORTER_FIELD_YESWIKILIST_URL_HELP' => 'https://mon-wiki-distant.fr/?api/forms/12/entries&fields=id_fiche,bf_titre வடிவில் : பட்டியலை உருவாக்கப் பதிவுகளின் அடையாளமும் தலைப்பும் மட்டுமே பயன்படும், &fields= மூலம் அவற்றை வெளிப்படையாகக் கேட்பது தொலைவிலுள்ள விக்கி அனைத்துப் பதிவுகளையும் முழுமையாக அனுப்புவதைத் தவிர்க்கும்.',
    'IMPORTER_FIELD_YESWIKITOYESWIKI_URL' => 'தொலைவிலுள்ள படிவத்தின் பதிவுகளின் Url (api json)',
    'IMPORTER_FIELD_YESWIKITOYESWIKI_URL_HELP' => 'https://mon-wiki-distant.fr/?api/forms/12/entries/json வடிவில் — தொலைவிலுள்ள படிவத்தின் அடையாளம் அதிலிருந்து ஊகிக்கப்படுகிறது. இந்த url உடன் சேர்க்கப்படும் அளவுருக்கள் (எடுத்துக்காட்டாக &query=bf_ville=Marseille) தக்கவைக்கப்படும், பதிவுகளில் ஒரு பகுதியை மட்டும் இறக்குமதி செய்ய.',
    'IMPORTER_FIELD_YESWIKITOYESWIKI_AUTH_HELP' => 'விருப்பத்தேர்வு. பொதுவில் உள்ள ஒரு தொலைவுப் படிவத்தை அநாமதேயமாகப் படிக்க, அடையாளத்தையும் கடவுச்சொல்லையும் காலியாக விடவும்; பொதுவில் படிக்க முடியாத ஒரு படிவத்திலிருந்து இறக்குமதி செய்ய, இரண்டையும் நிரப்பவும்.',
