அல்லது ஒரு பட்டியல் புலத்தின் (list, checkbox,..) மதிப்பைச் சோதிக்கலாம் (எ.கா: `test(bf_type,premiere_cle)`{br}
இது bf_type == premiere_cle எனில் 1 ஐயும் இல்லையெனில் 0 ஐயும் தரும்).',
    'BAZ_FORM_EDIT_MAP_GEOMETRIES' => 'காற்புள்ளியால் பிரிக்கப்பட்ட அனுமதிக்கப்பட்ட வடிவங்கள் (இவற்றில்: marker, line, polygon, rectangle, circle)',
    'BAZ_FORM_EDIT_MAP_MAX_GEOMETRIES' => 'வரைபடத்தில் வரையக்கூடிய வடிவங்களின் அதிகபட்ச எண்ணிக்கை',
