    'BAZ_FORM_EDIT_PLACEHOLDER' => 'உள்ளீட்டுக்கான குறிப்பு',
    'BAZ_FORM_TABS_HINT' => 'கீற்றுகளைப் பயன்படுத்த, உங்களுக்கு இரு புலங்கள் தேவை: {br} - "," ஆல் பிரிக்கப்பட்ட கீற்றுகளின் பெயர்களைக் குறிப்பிடும் "{tabs-field-label}" புலம் {br} - ஒவ்வொரு கீற்றின் இறுதியிலும், உங்கள் படிவத்தின் இறுதியிலும் சேர்க்க வேண்டிய "{tabchange-field-label}" புலம்',
    'BAZ_FORM_EDIT_LISTEFICHES_PARAMS_ADD_ENTRY_BTN_LABEL' => 'பட்டியலிலிருந்து பதிவைச் சேர்க்கும் பொத்தானின் உரை',
    'BAZ_BOOKMARKLET_HINT' => 'இந்தப் புலம் இயங்க வேறு இரு புலங்கள் தேவை:{br}
  - ஒரு url புலம் (இயல்பாக "bf_url"){br}
  - ஒரு நீள உரைப் புலம் (இயல்பாக "bf_description")',
    'BAZ_FORM_EDIT_CONDITIONS_CHECKING_HINT' => 'நிபந்தனை பின்வரும் வடிவத்தைப் பின்பற்ற வேண்டும் (` இல்லாமல்):{br}
 - ` and ` : மற்றும் என்பதைத் தரும்{br}
 - ` or ` : அல்லது என்பதைத் தரும்{br}
 - `==` : இதற்குச் சமம் என்பதைத் தரும்{br}
 - `!=` : இதிலிருந்து வேறுபட்டது என்பதைத் தரும் {br}
 - `match /Javascript Regular Expression (JRE)/JRE flags` : Javascript RegExp.test (JRE, JRE flags) முறையின் அதே முடிவைத் தரும்{br}
 - ` in [value1,value2]` : காற்புள்ளியால் பிரிக்கப்பட்டு அடைப்புக்குறிக்குள் உள்ள கூறுகளின் பட்டியலைச் சேர்ந்தது{br}
 - `|length > 6` : தேர்வு செய்யப்பட்ட கூறுகளின் எண்ணிக்கை 6 ஐ விட அதிகமா எனச் சரிபார்க்கிறது (">=","<","<=" உடனும் இயங்கும்){br}
 - ` == [value1,value2]` : காற்புள்ளியால் பிரிக்கப்பட்டு அடைப்புக்குறிக்குள் உள்ள கூறுகளின் பட்டியலுக்குச் சரியாகச் சமம் (checkbox-க்கு மட்டும்){br}
 - `(  )` நிபந்தனைகளைக் குழுவாக்க உதவுகிறது, இல்லையெனில் இடமிருந்து வலமாக முன்னுரிமை{br}
 - `!(  )` அல்லது `not (  )` நிபந்தனையின் மறுப்பு{br}
 - `==` அல்லது `!=` இன் இடதுபுறம் புலத்தின் பெயரைக் குறிக்கவும் எ.கா:`bf_thematique`{br}
 - ` is empty ` : மதிப்பு காலியாக உள்ளதா எனச் சரிபார்க்க உதவுகிறது{br}
 - ` is not empty ` : மதிப்பு காலியாக இல்லையா எனச் சரிபார்க்க உதவுகிறது{br}
 - தேவையற்ற இடைவெளிகள் தானாக நீக்கப்படும்{br}
 - செயல்பாடுகள் எழுத்து அளவுக்கு உணர்வற்றவை',
