    'SUPPORT_YESWIKI' => 'YesWiki-க்கு ஆதரவு தாருங்கள்',
    'SUPPORT_YESWIKI_DESC' => 'YesWiki ஒரு கட்டற்ற, இலவச மென்பொருள், ஆனால் இந்தப் புதிய பதிப்பை இயக்க உதவுவது உங்கள் நன்கொடைகளே',
    'SUPPORT_US' => 'எங்களுக்கு ஆதரவு தாருங்கள்',
    'DONATE' => 'நான் நன்கொடை தருகிறேன்',
    'LEARN_MORE' => 'மேலும் அறிய',
    'AU_UNABLE_TO_REMOVE_FILES' => 'கீழே உள்ள கோப்புகளையும்/அல்லது அடைவுகளையும் நீக்க முடியவில்லை.\\nஅவற்றின் எழுதும் அணுகல் உரிமைகளைச் சரிபார்க்கவும்.\\n',
    'AU_NOT_WRITABLE_FILES' => 'பின்வரும் கோப்புகள் மற்றும்/அல்லது அடைவுகள் இல்லை, அல்லது சேவையகத்தால் எழுத முடியாதவை:\\n',
    'AU_CANNOT_ARCHIVE' => 'பின்வரும் காரணம்(கள்) நிமித்தம் சேவையகத்தால் காப்புப்பிரதி எடுக்க முடியவில்லை: ',
    'AU_ALREADY_ARCHIVING' => 'ஒரு காப்புப்பிரதிச் செயல்பாடு ஏற்கனவே நடந்து கொண்டிருக்கிறது. \'wiki_status\' அமைவு அளவுருவின் மதிப்பை \'running\' என வைத்து wiki-யின் நிலையை மாற்றவும்.',
    'AU_SITE_IS_HIBERNATED' => 'தளம் வாசிப்பு மட்டும் நிலையில் உள்ளது. காப்புப்பிரதிகள் எடுக்க, தளம் இணையத்தில் இயங்க வேண்டும். \'wiki_status\' அமைவு அளவுருவின் மதிப்பை \'running\' என வைத்து wiki-யின் நிலையை மாற்றவும். ',
    'AU_PRIVATE_PATH_NOT_WRITABLE' => '\'private/backups\' அடைவில் எழுத முடியவில்லை. தானியங்கி காப்புப்பிரதி எடுக்க இந்த அடைவின் அணுகல் உரிமைகளைச் சரிபார்க்கவும், அல்லது \'preupdate_backup_activated\' ஐ \'false\' என வைத்து தானியங்கி காப்புப்பிரதி விருப்பத்தை நிறுத்தவும்.',
    'AU_PRIVATE_PATH_AVAILABLE_ON_INTERNET' => '\'private/backups\' அடைவு இணையத்திலிருந்து அணுகக்கூடியதாக உள்ளது. காப்பகங்களின் அணுகலைப் பாதுகாத்து தானியங்கி காப்புப்பிரதியை எடுக்க, சேவையகத்தின் அமைப்புகளைச் சரிபார்க்கவும் அல்லது நிர்வாகியைத் தொடர்பு கொள்ளவும். \'preupdate_backup_activated\' அமைவு அளவுருவை \'false\' என வைத்து தானியங்கி காப்புப்பிரதி விருப்பத்தையும் நிறுத்தலாம்.',
    'AU_CANNOT_EXECUTE_BACKUP' => 'தானியங்கி காப்புப்பிரதியை ஒத்திசைவற்ற முறையில் இயக்கும் திறன் சேவையகத்திற்கு இல்லை. \'call_archive_async\' அமைவு அளவுருவை \'false\' என மாற்றவும்.',
    'AU_NOT_ENOUGHT_SPACE' => 'காப்புப்பிரதி எடுக்கப் போதிய இடம் வட்டில் இல்லை. இடத்தைக் காலி செய்யவும், அல்லது \'preupdate_backup_activated\' தானியங்கி காப்புப்பிரதி விருப்பத்தை \'false\' என வைத்து நிறுத்தவும்.',
