    'EDIT_CONFIG_HINT_USER_ACTIVATION_KEY_LENGTH' => 'பயனர்களின் செயல்படுத்தும் சாவியின் நீளம்',
    'LOGIN_PASSWORD_FORMAT_OBSOLETE' => 'இந்தப் பதிப்பு ஏற்காத ஒரு வடிவத்தில் உங்கள் கடவுச்சொல் சேமிக்கப்பட்டிருந்தது. புதிய ஒன்றைத் தேர்ந்தெடுக்க « கடவுச்சொல் தொலைந்ததா? » இணைப்பைப் பயன்படுத்தவும் — உங்கள் கணக்கும் உள்ளடக்கமும் பாதிக்கப்படவில்லை.',
    'LOGIN_PASSWORD_FORMAT_OBSOLETE_ASK_ADMIN' => 'இந்தப் பதிப்பு ஏற்காத ஒரு வடிவத்தில் உங்கள் கடவுச்சொல் சேமிக்கப்பட்டிருந்தது. அதை மீட்டமைக்க ஒரு நிர்வாகியிடம் கேளுங்கள் — உங்கள் கணக்கும் உள்ளடக்கமும் பாதிக்கப்படவில்லை.',
    'LOGIN_PASSWORD_FOR' => 'இதற்கான கடவுச்சொல்',
    'LINK_TO_CHANGE_PASSWORD' => 'கடவுச்சொல்லை மாற்றுவதற்கான இணைப்பு',
    'RECOVERY_MESSAGE_SENT' => 'கடவுச்சொல்லை மீட்டமைக்கும் வழிமுறைகளுடன் ஒரு செய்தி {email} க்கு அனுப்பப்பட்டது',
    'RECOVERY_LINK' => 'கடவுச்சொல்லை மீட்டமைக்கும் இணைப்பு',
    'USERSETTINGS_CHANGE_PWD_IN_IFRAME' => 'நீங்கள் ஒரு iframe வகைச் சாளரத்தில் உங்கள் கடவுச்சொல்லை மாற்றப் போகிறீர்கள்.
விசை பதிவு தாக்குதல்களைத் தவிர்க்க, தளத்தின் url {baseUrl} என்பதில் தொடங்குகிறதா என்பதை உறுதிசெய்யவும்.
சிறிதளவு சந்தேகம் இருந்தாலும், {link} இணைப்பைச் சொடுக்கி இந்தப் படிவத்தைத் தனிப் பக்கத்தில் திறக்கவும்.',
    'USERSETTINGS_NAME_NOT_FOUND' => '"{currentName}" என்ற அடையாளம் இல்லை!',
    'AB_checkcontent_label' => 'பதிவுகளைச் சரிபார்',
    'AB_checkcontent_action_description' => 'மதிப்புகள் படிவத்துடன் இனி பொருந்தாத பதிவுகளைப் பட்டியலிடுகிறது: காலியான கட்டாயப் புலங்கள், பட்டியலுக்கு வெளியே உள்ள மதிப்புகள், நீக்கப்பட்ட பதிவுகளுக்கான இணைப்புகள், தவறான வடிவில் உள்ள மின்னஞ்சல் முகவரிகள், தேதிகள், வலை முகவரிகள், படிவம் இனி வரையறுக்காத புலங்கள். நிர்வாகிகளுக்கு மட்டும்.',
    'AB_checkcontent_textreplace_label' => 'காலியான கட்டாயப் புலங்களுக்கான மாற்று உரை',
    'AB_checkcontent_textreplace_hint' => 'ஒரு கட்டாய உரை அல்லது நீள உரைப் புலம் காலியாக இருக்கும்போது மதிப்பாக முன்மொழியப்படும். இயல்பாக, தளத்தின் மொழியிலுள்ள சொற்றொடர். எதையும் முன்மொழியாமல் இந்தப் பதிவுகளைக் கையால் திருத்த, காலியாக விடவும்.',
    'AB_checkcontent_forcevalues_label' => 'காலியான கட்டாயப் புலங்களில் வைக்க வேண்டிய மதிப்புகள்',
    'AB_checkcontent_forcevalues_hint' => 'காற்புள்ளியால் பிரிக்கப்பட்ட `புலம்=மதிப்பு` இணைகள், எடுத்துக்காட்டாக `bf_type=atelier,bf_date=2014-12-23`. இங்கே பெயரிடப்பட்ட ஒவ்வொரு காலியான கட்டாயப் புலமும் இந்த மதிப்பு ஏற்கனவே தேர்ந்தெடுக்கப்பட்டு, அதன் வரி ஏற்கனவே தேர்வு செய்யப்பட்டு வரும்; எனவே சரிசெய்தல் அதை எழுதும். பல மதிப்புகள் கொண்ட ஒரு புலத்தை நிரப்ப, பெயரை மீண்டும் எழுதவும். பட்டியல் இனி வழங்காத மதிப்பு புறக்கணிக்கப்படும்.',
