    'BAZ_INTRO_MODIFIER_FORMULAIRE' => 'ஒரு படிவத்தைத் திருத்த, அதன் பெயரிலோ பென்சில் படவுருவிலோ சொடுக்கவும். ஒரு படிவத்தை நீக்க, குப்பைத் தொட்டிப் படவுருவில் சொடுக்கவும்.<br /> ஒரு புதிய படிவத்தை உருவாக்க, இந்தப் பட்டியலுக்குக் கீழே உள்ள இணைப்பில் சொடுக்கவும்.',
    'BAZ_INTRO_AJOUT_LISTE' => '<strong>இதுவரை எந்தப் பட்டியலும் உருவாக்கப்படவில்லை.</strong><br />ஒரு புதிய பட்டியலை நீங்களே உருவாக்கலாம் (கூட்டல் குறியுள்ள பொத்தானைச் சொடுக்கவும்),<br />அல்லது ஏற்கனவே உள்ள ஒரு YesWiki இலிருந்து (எடுத்துக்காட்டாக https://yeswiki.net/serveur) பட்டியல்களை இறக்குமதி செய்யலாம்.',
    'BAZ_INTRO_AJOUT_FORMULAIRE' => '<strong>இதுவரை எந்தப் படிவமும் உருவாக்கப்படவில்லை.</strong><br />ஒரு புதிய படிவத்தை நீங்களே உருவாக்கலாம் (கூட்டல் குறியுள்ள பொத்தானைச் சொடுக்கவும்),<br />அல்லது ஏற்கனவே உள்ள ஒரு YesWiki இலிருந்து (எடுத்துக்காட்டாக https://yeswiki.net/serveur) படிவங்களை இறக்குமதி செய்யலாம்.',
    'BAZ_FORMULAIRE_VIDE' => 'இந்தப் படிவத்தின் அனைத்துப் பதிவுகளும் நீக்கப்பட்டுவிட்டன.',
    'BAZ_VIDER_FORMULAIRE' => 'இந்தப் படிவத்தின் அனைத்துத் தரவுகளையும் காலி செய்',
    'BAZ_FORM_DELETE' => '%{formId} படிவத்தை நீக்கு:',
