    'BAZ_CONFIRM_VIDER_FORMULAIRE' => 'கவனம்! இந்தப் படிவத்திற்குச் சேமிக்கப்பட்ட அனைத்துப் பதிவுகளும் இழக்கப்படும், காலியான படிவம் மட்டுமே எஞ்சியிருக்கும்.. இந்தப் படிவத்தை அதனுடன் தொடர்புடைய பதிவுகளிலிருந்து காலி செய்ய விரும்புகிறீர்கள் என்பது உறுதியா',
    'BAZ_CONFIRM_SUPPRIMER_FORMULAIRE' => 'கவனம்! சேமிக்கப்பட்ட அனைத்துத் தரவுகளும் இழக்கப்படும்.. இந்த வகைப் படிவத்தையும் அதனுடன் தொடர்புடைய அனைத்துப் பதிவுகளையும் நீக்க விரும்புகிறீர்கள் என்பது உறுதியா',
    'BAZ_CONFIRM_SUPPRIMER_LISTE' => 'கவனம்! சேமிக்கப்பட்ட அனைத்துத் தரவுகளும் இழக்கப்படும்.. இந்தப் பட்டியலையும் அதனுடன் தொடர்புடைய அனைத்துத் தரவுகளையும் நீக்க விரும்புகிறீர்கள் என்பது உறுதியா',
