    'EDIT_CONFIG_HINT_BAZ_ENVOI_MAIL_ADMIN' => 'ஒவ்வொரு பதிவு மாற்றத்திற்கும் நிர்வாகிகளுக்கு மின்னஞ்சல் அனுப்பு (true அல்லது false)',
    'EDIT_CONFIG_HINT_BAZ_EXTERNAL_SERVICE[CACHE_TIME_TO_CHECK_CHANGES]' => 'JSON கோரிக்கைகளில் சேர்த்தல்களையும் மாற்றங்களையும் சரிபார்க்க, தற்காலிகச் சேமிப்பை இரு முறை புதுப்பிப்பதற்கு இடையிலான நேரம் (வினாடிகள்)',
    'EDIT_CONFIG_HINT_BAZ_EXTERNAL_SERVICE[CACHE_TIME_TO_CHECK_DELETION]' => 'JSON கோரிக்கைகளில் நீக்கங்களைச் சரிபார்க்க, தற்காலிகச் சேமிப்பை இரு முறை புதுப்பிப்பதற்கு இடையிலான நேரம் (வினாடிகள்)',
    'EDIT_CONFIG_HINT_BAZ_EXTERNAL_SERVICE[CACHE_TIME_TO_REFRESH_FORMS]' => 'JSON கோரிக்கைகளுக்குத் தேவையான படிவங்களுக்காக, தற்காலிகச் சேமிப்பை இரு முறை புதுப்பிப்பதற்கு இடையிலான நேரம் (வினாடிகள்)',
    'BAZ_USER_FIELD_EXISTING_USER_BY_NAME' => '"{currentName}" என்ற அடையாளங்குறி ஏற்கனவே உள்ளது!
அதை "{proposedName}" ஆல் மாற்றுவதை உறுதிப்படுத்தப் பெட்டியில் குறியிடவும், அல்லது கீழே உள்ள படிவத்தில் உங்கள் அடையாளங்குறியை மாற்றவும்.',
    'BAZ_USER_FIELD_EXISTING_USER_BY_EMAIL' => 'வழங்கிய மின்னஞ்சல் ஏற்கனவே ஒரு YesWiki கணக்குடன் தொடர்புடையது! வேறொரு மின்னஞ்சல் முகவரியை உள்ளிடவும் அல்லது அந்தக் கணக்கில் உள்நுழையவும்.',
    'BAZ_USER_FIELD_ALREADY_CONNECTED' => 'நீங்கள் ஏற்கனவே "{wikiname}" என்ற அடையாளங்குறியுடனும் "{email}" என்ற மின்னஞ்சலுடனும் உள்நுழைந்துள்ளீர்கள்.
உருவாக்கப்படும் பதிவு தானாகவே உங்கள் கணக்குடன் இணைக்கப்படும். புதிய கணக்கை உருவாக்க வெளியேறவும்!',
    'BAZ_USER_FIELD_ALREADY_CONNECTED_AUTOUPDATE' => 'இந்தக் கணக்குடன் தொடர்புடைய மின்னஞ்சல் முகவரியை மாற்ற, "{email}" இலிருந்து வேறுபட்ட ஒன்றைத் தட்டச்சு செய்யவும்.',
    'BAZ_USER_FIELD_FORCE_SAVE_ENTRY' => 'நிர்வாகியாக, கொடுக்கப்பட்ட மின்னஞ்சலுக்குப் பதிவை உருவாக்குவதைக் கட்டாயப்படுத்து (கணக்கு ஏற்கனவே இல்லையெனில் மட்டும் ஒன்றை உருவாக்கு)',
